import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def point_clouds(ctx):
    features = torch.randn(6, generator=ctx.rng.torch)
    points = torch.randn(3, 3, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(points)}
dataset = synth.Spec("chamfer-point-clouds", generator=point_clouds, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class PointCloudPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=6, out_features=6)
    def forward(self, inputs):
        return {"points": self.network(inputs).reshape(-1, 2, 3)}
trainer = Trainer(PointCloudPredictor(), train, recipe="structured-objective", recipe_config={"loss": "chamfer", "bindings": {"logits_or_prediction": {"output": "points"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
